import{_ as l,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"معايير قوى الأبعاد العليا","description":"","frontmatter":{},"headers":[],"relativePath":"ar/17-位面至高强者标准.md","filePath":"ar/17-位面至高强者标准.md","lastUpdated":null}'),e={name:"ar/17-位面至高强者标准.md"};function o(h,a,d,n,s,u){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="معايير-قوى-الأبعاد-العليا" tabindex="-1">معايير قوى الأبعاد العليا <a class="header-anchor" href="#معايير-قوى-الأبعاد-العليا" aria-label="Permalink to &quot;معايير قوى الأبعاد العليا&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>17</td></tr><tr><td>الوحدة</td><td>القوانين الكونية وأنظمة الزراعة</td></tr><tr><td>الكلمات المفتاحية</td><td>قوة البعد العليا، معايير القوى، تنشيط 20%، مرتبة الأصل، مسؤولية القوى</td></tr></tbody></table><h2 id="أولاً-تعريف-قوى-الأبعاد-العليا-وموقعها" tabindex="-1">أولاً: تعريف قوى الأبعاد العليا وموقعها <a class="header-anchor" href="#أولاً-تعريف-قوى-الأبعاد-العليا-وموقعها" aria-label="Permalink to &quot;أولاً: تعريف قوى الأبعاد العليا وموقعها&quot;">​</a></h2><p>«قوة البعد العليا» هو اللقب الرسمي الذي تطلقه حضارة التكافل المرساة على المزارعين البالغين مستوى القوة الكونية، وهم القمم من المزارعين الذين تكفي قوتهم لدعم استقرار قوانين بُعدٍ ما استقلالاً، ويستطيعون التأثير على المستوى الكوني. في المعيار الموحد لتقسيم المراتب، تقابل قوى الأبعاد العليا المرتبة التاسعة «مرتبة الأصل» فما فوق، وهي مجموعة القوة القصوى في هينغ يوانتشو.</p><p>قوة البعد العليا ليست لقب مرتبة قوة فحسب، بل تحديد مسؤولية وهوية. في إطار الحضارة التكافلية، كلما كبرت القوة كبرت المسؤولية. قوى الأبعاد العليا ليسوا ناجحين في الزراعة الشخصية فحسب، بل حراس الحضارة، وصانة القوانين، وهداة المتأخرين. الهدف الأساسي لـ«استراتيجية التنشيط بنسبة 20%» في الحضارة التكافلية هو تنشيط، في المرحلة المبكرة من قيام الحضارة، 20% من إجمالي الكائنات لبلوغ مرتبة قوة البعد العليا، تمهيداً لأساس قوة الصعود الكلي للكون.</p><p>تجدر الإشارة خاصة إلى أن «قوة البعد العليا» في الحضارة التكافلية تختلف جوهرياً عن «جبار البعد» في عصر الافتراس. كان جبابرة الأبعاد في عصر الافتراس يستعبدون الأبعاد بالقوة وينهبون الموارد، وهم حكام الأبعاد ونهّابوها؛ أما قوى الأبعاد العليا في الحضارة التكافلية فيحمون الأبعاد بالقوة ويخدمون الكائنات، وهم حراس الأبعاد وخدّامها. هذا الفرق تجسيد مباشر للفكرة الأساسية لمكافحة الافتراس في الحضارة التكافلية على مستوى الأقوياء.</p><h2 id="ثانياً-معايير-تقييم-قوى-الأبعاد-العليا" tabindex="-1">ثانياً: معايير تقييم قوى الأبعاد العليا <a class="header-anchor" href="#ثانياً-معايير-تقييم-قوى-الأبعاد-العليا" aria-label="Permalink to &quot;ثانياً: معايير تقييم قوى الأبعاد العليا&quot;">​</a></h2><p>يعتمد تقييم قوى الأبعاد العليا «نظام التقييم رباعي الأبعاد»؛ ولا يُعترف رسمياً بقوة البعد العليا إلا عند بلوغ الأبعاد الأربعة جميعها المعايير:</p><table tabindex="0"><thead><tr><th>البعد</th><th>محتوى التقييم</th><th>معيار النجاح</th><th>الوزن</th></tr></thead><tbody><tr><td>بُعد القوة</td><td>المرتبة، مستوى الطاقة، القدرة على التحكم بالقوانين</td><td>بلوغ المرتبة التاسعة للمعيار الموحد (مرتبة الأصل)، والقدرة على تحريك قوة الأصل استقلالاً</td><td>40%</td></tr><tr><td>بُعد الطباع</td><td>النضج العقلي، التمسك بالأخلاق، موقف مكافحة الافتراس</td><td>اجتياز الفحص الأخلاقي لمحكمة المراسي، وتأكيد التمسك بمبادئ مكافحة الافتراس وفكرة التكافل</td><td>25%</td></tr><tr><td>بُعد المساهمة</td><td>المساهمة في الشبكة التكافلية وتطور الحضارة والتقدم المشترك لعشرة آلاف عرق</td><td>بلوغ قيمة المساهمة مستوى أعلى 20% من الحضارة، مع سجل مساهمة واحد على مستوى الحضارة على الأقل</td><td>20%</td></tr><tr><td>بُعد المسؤولية</td><td>الرغبة والقدرة على تحمل المسؤوليات العامة</td><td>الرغبة والقدرة على تحمل مسؤوليات عامة فوق مستوى البعد (كصيانة المراسي وحماية الحضارة وغيرها)</td><td>15%</td></tr></tbody></table><p>يجسد تصميم نظام الأبعاد الأربعة فلسفة تقييم القوى في الحضارة التكافلية «الجمع بين الفضيلة والموهبة، وتقديم الفضيلة». القوة أساس فقط؛ والطباع والمساهمة والمسؤولية معايير لا تقل ضرورة. فالمزارع القوي ذو الطباع الخبيثة الرافض للمسؤولية، حتى لو بلغ مستوى قوة مرتبة الأصل، لن يُعترف به «قوة بعد عليا»، بل يصنف «فرداً عالي الخطورة» ويخضع لرقابة وقيود موافقة.</p><h2 id="ثالثاً-المعايير-التفصيلية-لبُعد-القوة" tabindex="-1">ثالثاً: المعايير التفصيلية لبُعد القوة <a class="header-anchor" href="#ثالثاً-المعايير-التفصيلية-لبُعد-القوة" aria-label="Permalink to &quot;ثالثاً: المعايير التفصيلية لبُعد القوة&quot;">​</a></h2><p>بُعد القوة هو أساس تقييم قوى الأبعاد العليا، ومعاييره التفصيلية:</p><h3 id="_3-1-معايير-المرتبة" tabindex="-1">3.1 معايير المرتبة <a class="header-anchor" href="#_3-1-معايير-المرتبة" aria-label="Permalink to &quot;3.1 معايير المرتبة&quot;">​</a></h3><ul><li>بلوغ المرتبة التاسعة «مرتبة الأصل» في المعيار الموحد، وملامسة القوانين الأصلية للكون</li><li>القدرة على تحريك قوة الأصل باستقرار، لا تحريكاً انفجارياً عارضاً</li><li>اندماج عميق بين الداو الشخصي والقوانين الأصلية للكون، وبلوغ حالة «الداو هو الأصل، والأصل هو الداو»</li></ul><h3 id="_3-2-معايير-الطاقة" tabindex="-1">3.2 معايير الطاقة <a class="header-anchor" href="#_3-2-معايير-الطاقة" aria-label="Permalink to &quot;3.2 معايير الطاقة&quot;">​</a></h3><ul><li>بلوغ الطاقة الأصلية المخزنة في الجسد «مستوى البعد» — أي كفاية مجموع الطاقة لدعم عمل القوانين الأساسية لبُعد متوسط</li><li>بلوغ نقاء الطاقة أكثر من 99%، بلا شوائب تقريباً</li><li>بلوغ سرعة استشفاف الطاقة «الاستشفاف اللحظي» — حتى بعد استهلاك هائل في القتال، التعافي الكامل في وقت قصير للغاية</li></ul><h3 id="_3-3-معايير-التحكم-بالقوانين" tabindex="-1">3.3 معايير التحكم بالقوانين <a class="header-anchor" href="#_3-3-معايير-التحكم-بالقوانين" aria-label="Permalink to &quot;3.3 معايير التحكم بالقوانين&quot;">​</a></h3><ul><li>القدرة على تحريك قوة القوانين والتحكم بها على المستوى الكوني</li><li>المشاركة في الضبط الدقيق للقوانين الكونية وتحسينها، والتأثير الفعلي في عمل القوانين</li><li>القدرة على التنقل والعمل بين الأبعاد استقلالاً دون دعم المراسي</li><li>القدرة على خلق عوالم كاملة ومنظومات قوانين في فضاء العزل (قدرة مرتبة خلق العالم)</li></ul><h3 id="_3-4-معايير-شكل-الحياة" tabindex="-1">3.4 معايير شكل الحياة <a class="header-anchor" href="#_3-4-معايير-شكل-الحياة" aria-label="Permalink to &quot;3.4 معايير شكل الحياة&quot;">​</a></h3><ul><li>إكمال شكل الحياة تطوره عالي الأبعاد، والقدرة على الوجود والعمل في البعد المادي وطبقة الطاقة ومجال الوعي معاً</li><li>شبه الخلود — لا تشكل الهجمات والأضرار الاعتيادية تهديداً مميتاً؛ ولا تؤذيه حقاً إلا قوة من مستواه أو أعلى</li><li>القدرة على تثبيت بصمة حياته في أصل الكون، والقدرة على البعث عبر التثبيت بالأصل حتى لو دُمر الجسد المادي</li></ul><h2 id="رابعاً-المعايير-التفصيلية-لبُعد-الطباع" tabindex="-1">رابعاً: المعايير التفصيلية لبُعد الطباع <a class="header-anchor" href="#رابعاً-المعايير-التفصيلية-لبُعد-الطباع" aria-label="Permalink to &quot;رابعاً: المعايير التفصيلية لبُعد الطباع&quot;">​</a></h2><p>بُعد الطباع هو أكثر أجزاء تقييم القوى في الحضارة التكافلية تميزاً، وهو الفرق الجوهري عن عصر الافتراس:</p><h3 id="_4-1-موقف-مكافحة-الافتراس" tabindex="-1">4.1 موقف مكافحة الافتراس <a class="header-anchor" href="#_4-1-موقف-مكافحة-الافتراس" aria-label="Permalink to &quot;4.1 موقف مكافحة الافتراس&quot;">​</a></h3><ul><li>الإيمان بمكافحة الافتراس وممارستها من الجذر، دون أي سجل زراعة افتراسية قط</li><li>عدم اختيار الإنقاذ الذاتي على حساب الافتراس على الآخرين حتى في الشدائد القصوى</li><li>مقاومة أي شكل من أشكال الافتراس ومعارضته بنشاط، والجرأة على قول لا للقوى الافتراسية</li></ul><h3 id="_4-2-فكرة-التكافل" tabindex="-1">4.2 فكرة التكافل <a class="header-anchor" href="#_4-2-فكرة-التكافل" aria-label="Permalink to &quot;4.2 فكرة التكافل&quot;">​</a></h3><ul><li>الفهم العميق والإيمان بالفكرة الأساسية للحضارة «تكافل عشرة آلاف عرق، وصعود الكون»</li><li>تقديم المصالح التكافلية أولاً في الزراعة الشخصية والشؤون العامة</li><li>المشاركة الفعالة في بناء الشبكة التكافلية وصيانتها، والاستعداد لمشاركة ثمار الزراعة والمعرفة مع الكائنات</li></ul><h3 id="_4-3-النضج-العقلي" tabindex="-1">4.3 النضج العقلي <a class="header-anchor" href="#_4-3-النضج-العقلي" aria-label="Permalink to &quot;4.3 النضج العقلي&quot;">​</a></h3><ul><li>استقرار عاطفي، وعدم الإضرار بالحضارة والكائنات بسبب المشاعر الشخصية</li><li>امتلاك رؤية كونية عظيمة ونظرة تاريخية بعيدة، وعدم التضحية بالتنمية البعيدة لمكاسب قريبة</li><li>القدرة على تحمل الضغوط والإخفاقات الهائلة، مع الحفاظ على العقلانية والثبات في الشدائد</li></ul><h3 id="_4-4-الفحص-الأخلاقي" tabindex="-1">4.4 الفحص الأخلاقي <a class="header-anchor" href="#_4-4-الفحص-الأخلاقي" aria-label="Permalink to &quot;4.4 الفحص الأخلاقي&quot;">​</a></h3><p>ينفذ تقييم بُعد الطباع «لجنة الفحص الأخلاقي» التابعة لمحكمة المراسي، وطرق الفحص:</p><ul><li>فحص السلوك التاريخي: فحص جميع سجلات السلوك المهمة للمزارع عبر التاريخ</li><li>المسح الوعائي العميق: بموافقة المزارع الطوعية، إجراء مسح عميق على مستوى الوعي، وتأكيد حقيقة أفكاره الداخلية</li><li>اختبار الضغط الظرفي: وضع معضلات أخلاقية قصوى في بيئات محاكاة، ومراقبة اختيارات المزارع</li><li>المراقبة الطويلة: للمرشحين المثيرين للجدل، إجراء مراقبة وتقييم على مدى عدة سنوات</li></ul><h2 id="خامساً-المعايير-التفصيلية-لبُعد-المساهمة" tabindex="-1">خامساً: المعايير التفصيلية لبُعد المساهمة <a class="header-anchor" href="#خامساً-المعايير-التفصيلية-لبُعد-المساهمة" aria-label="Permalink to &quot;خامساً: المعايير التفصيلية لبُعد المساهمة&quot;">​</a></h2><p>يقيس بُعد المساهمة مساهمة المزارع الفعلية في الحضارة التكافلية والتقدم المشترك لعشرة آلاف عرق:</p><h3 id="_5-1-أنواع-المساهمة" tabindex="-1">5.1 أنواع المساهمة <a class="header-anchor" href="#_5-1-أنواع-المساهمة" aria-label="Permalink to &quot;5.1 أنواع المساهمة&quot;">​</a></h3><ul><li><strong>المساهمة الزراعية</strong>: الأثر القدوة لاختراقات المراتب، وخلق الطرائق الجديدة، وابتكار النظريات الزراعية</li><li><strong>المساهمة المعرفية</strong>: المشاركة العلنية بالتجارب الزراعية، وأعمال التعليم والتدريب، ونتائج البحث الأكاديمي</li><li><strong>المساهمة التقنية</strong>: ابتكار تقنيات هندسة القوانين، وتحسين تقنية ثمرة المضاعفة، وتطوير عتاد المراسي</li><li><strong>المساهمة الخدمية</strong>: صيانة المراسي، وحكم الحضارة، وإرشاد الأساتذة، والتنسيق بين الأعراق</li><li><strong>المساهمة البيئية</strong>: إصلاح بيئة الكواكب، وتحسين تداول طاقة الأبعاد، وحماية البيئة الكونية</li><li><strong>المساهمة الحمائية</strong>: صد التهديدات الخارجية، وحماية أمن الحضارة، وإنقاذ الأرواح في الكوارث</li></ul><h3 id="_5-2-تحديد-المساهمة-كمياً" tabindex="-1">5.2 تحديد المساهمة كمياً <a class="header-anchor" href="#_5-2-تحديد-المساهمة-كمياً" aria-label="Permalink to &quot;5.2 تحديد المساهمة كمياً&quot;">​</a></h3><p>تسجل شبكة المراسي قيمة المساهمة وتحسبها تلقائياً؛ وتُعطى أنواع المساهمة المختلفة أوزاناً مختلفة حسب أثرها وقيمتها. معيار قوى الأبعاد العليا: «بلوغ قيمة المساهمة مستوى أعلى 20% من الحضارة»، مع وجود مساهمة واحدة على الأقل «على مستوى الحضارة» — مساهمة ذات أثر كبير وبعيد في تطور الحضارة كلها.</p><h2 id="سادساً-المعايير-التفصيلية-لبُعد-المسؤولية" tabindex="-1">سادساً: المعايير التفصيلية لبُعد المسؤولية <a class="header-anchor" href="#سادساً-المعايير-التفصيلية-لبُعد-المسؤولية" aria-label="Permalink to &quot;سادساً: المعايير التفصيلية لبُعد المسؤولية&quot;">​</a></h2><p>يقيس بُعد المسؤولية رغبة المزارع وقدرته على تحمل المسؤوليات العامة:</p><h3 id="_6-1-أنواع-المسؤولية" tabindex="-1">6.1 أنواع المسؤولية <a class="header-anchor" href="#_6-1-أنواع-المسؤولية" aria-label="Permalink to &quot;6.1 أنواع المسؤولية&quot;">​</a></h3><p>المسؤوليات العامة الواجبة على قوى الأبعاد العليا:</p><ul><li><strong>حراسة المراسي</strong>: المسؤولية عن حراسة مرساة أو أكثر من المراسي المتقدمة وصيانتها</li><li><strong>مستشار الحضارة</strong>: العمل كمستشار أعلى مستوى للحضارة، والمشاركة في قرارات اتجاه تطورها</li><li><strong>وراثة الأساتذة</strong>: تدريب الجيل التالي من المزارعين وإرشاده، خاصة البذور المرشحة المؤهلة لبلوغ المراتب العليا</li><li><strong>جولة الأبعاد</strong>: جولات دورية على الأبعاد، ومراقبة استقرارها وتطور الحضارة</li><li><strong>الاستجابة للأزمات</strong>: الاضطلاع بأهم مهام الاستجابة عندما تواجه الحضارة أزمات كبرى (كانهيار الأبعاد والغزو الخارجي)</li><li><strong>المشاركة في القوانين</strong>: المشاركة في الضبط الدقيق للقوانين الكونية وتحسينها، والمساهمة في صعود الكون الكلي</li></ul><h3 id="_6-2-طرق-تحمل-المسؤولية" tabindex="-1">6.2 طرق تحمل المسؤولية <a class="header-anchor" href="#_6-2-طرق-تحمل-المسؤولية" aria-label="Permalink to &quot;6.2 طرق تحمل المسؤولية&quot;">​</a></h3><p>يمكن لقوى الأبعاد العليا اختيار أنواع المسؤولية التي تركز عليها حسب اهتماماتها وقدراتها، لكن لا يجوز لها رفض تحمل المسؤوليات العامة رفضاً كاملاً. تطبق الحضارة التكافلية «نظام إلزام الأقوياء» — فالمزارعون البالغون مرتبة قوة البعد العليا ملزمون بتخصيص جزء من قوتهم للشؤون العامة؛ والمدة المحددة استثمار 30% على الأقل من وقتهم وطاقتهم في المسؤوليات العامة سنوياً.</p><h2 id="سابعاً-استراتيجية-التنشيط-بنسبة-20" tabindex="-1">سابعاً: استراتيجية التنشيط بنسبة 20% <a class="header-anchor" href="#سابعاً-استراتيجية-التنشيط-بنسبة-20" aria-label="Permalink to &quot;سابعاً: استراتيجية التنشيط بنسبة 20%&quot;">​</a></h2><p>«استراتيجية التنشيط بنسبة 20%» من الاستراتيجيات الأساسية للحضارة التكافلية في مرحلتها المبكرة؛ هدفها تنشيط، في العصر الأول بعد قيام الحضارة، 20% من إجمالي الكائنات لبلوغ مرتبة قوة البعد العليا.</p><h3 id="_7-1-الأهداف-الاستراتيجية" tabindex="-1">7.1 الأهداف الاستراتيجية <a class="header-anchor" href="#_7-1-الأهداف-الاستراتيجية" aria-label="Permalink to &quot;7.1 الأهداف الاستراتيجية&quot;">​</a></h3><ul><li>الهدف القريب (خلال 100 سنة من قيام الحضارة): تنشيط 1% من الكائنات لبلوغ مرتبة الأصل</li><li>الهدف المتوسط (خلال 500 سنة): تنشيط 10% من الكائنات لبلوغ مرتبة الأصل</li><li>الهدف البعيد (خلال 1000 سنة): تنشيط 20% من الكائنات لبلوغ مرتبة الأصل</li></ul><h3 id="_7-2-الدعم-الاستراتيجي" tabindex="-1">7.2 الدعم الاستراتيجي <a class="header-anchor" href="#_7-2-الدعم-الاستراتيجي" aria-label="Permalink to &quot;7.2 الدعم الاستراتيجي&quot;">​</a></h3><p>يعتمد تنفيذ الاستراتيجية على الشروط الداعمة التالية:</p><ul><li><strong>فتح الأنظمة الثلاثمائة</strong>: توفير خيارات زراعية غنية للكائنات</li><li><strong>نشر تقنية ثمرة المضاعفة</strong>: تضخيم الاستدلال الزراعي بمئة ضعف يرفع الكفاءة الزراعية كثيراً</li><li><strong>نظام العقود المرتبطة بالإنتاج</strong>: توفير دعم موارد مستقر للمزارعين</li><li><strong>منظومة ضمان طريق لكل إنسان</strong>: ضمان شروط زراعية أساسية لكل كائن</li><li><strong>شبكة الأساتذة</strong>: إرشاد المزارعين المتقدمين للمبتدئين، مسرعين تدريب الكفاءات</li></ul><h3 id="_7-3-الأهمية-الاستراتيجية" tabindex="-1">7.3 الأهمية الاستراتيجية <a class="header-anchor" href="#_7-3-الأهمية-الاستراتيجية" aria-label="Permalink to &quot;7.3 الأهمية الاستراتيجية&quot;">​</a></h3><p>أهمية الاستراتيجية ليست في تدريب عدد كبير من القوى فحسب، بل في:</p><ul><li>توفير أساس قوة كافٍ لصعود الكون الكلي</li><li>تكوين جماعة قوى واسعة، مانعة احتكار القوة من أفراد</li><li>تكوين جو حضاري «تتوالى فيه القوى»، ملهمةً مزيداً من الكائنات للزراعة المجتهدة</li><li>توفير أساس قوى واسع لجمهورية عشرة آلاف عرق، مضمونةً لكل عرق ممثليه الأعلى</li></ul><h2 id="ثامناً-حقوق-قوى-الأبعاد-العليا-ومعاملتها" tabindex="-1">ثامناً: حقوق قوى الأبعاد العليا ومعاملتها <a class="header-anchor" href="#ثامناً-حقوق-قوى-الأبعاد-العليا-ومعاملتها" aria-label="Permalink to &quot;ثامناً: حقوق قوى الأبعاد العليا ومعاملتها&quot;">​</a></h2><p>مقابل مسؤولياتها، تتمتع قوى الأبعاد العليا بالحقوق والمعاملة التالية:</p><ul><li><strong>أولوية الموارد</strong>: التمتع بأعلى أولوية في توزيع موارد الزراعة</li><li><strong>حق المشاركة في القوانين</strong>: حق المشاركة في قرارات الضبط الدقيق للقوانين الكونية وتحسينها</li><li><strong>حق خلق الفضاءات</strong>: حق إنشاء فضاءات أو عوالم مستقلة خاصة بها</li><li><strong>حق قرار الحضارة</strong>: مقاعد وأصوات في أعلى هيئة قرار للحضارة</li><li><strong>حق التنقل بين الأبعاد</strong>: حرية التنقل في جميع الأبعاد الخاضعة للحضارة التكافلية</li><li><strong>الشرف والإجلال</strong>: نيل احترام الحضارة كلها وإجلالها، وتدوين مآثرهم في سجلات الحضارة</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>معايير قوى الأبعاد العليا هي إعادة تعريف حضارة التكافل المرساة لمفهوم «القوي». ففي الحضارة التكافلية، القوي ليس مفترساً ولا جباراً ولا حاكماً متعالياً، بل حارساً وخادماً وهادياً. بُعد القوة أساس، وبُعد الطباع روح، وبُعد المساهمة قيمة، وبُعد المسؤولية اضطلاع — باتحاد الأبعاد الأربعة يكون المرء «قوة بعد عليا» حقيقية. هدف استراتيجية التنشيط بنسبة 20% ليس تدريب 20% من القوى فحسب، بل تدريب 20% من الحراس المستعدين لتحمل مسؤولية تكافل عشرة آلاف عرق وصعود الكون. عندما يبلغ 20% من الكائنات مرتبة قوة البعد العليا ويطبقون فكرة التكافل، فلن يكون الصعود الكلي للكون حلماً بعيداً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (التقسيم الموحد لمراتب الزراعة)</li><li>23-20%激活战略规划 (خطة استراتيجية التنشيط بنسبة 20%)</li><li>19-修炼伦理与边界 (أخلاقيات الزراعة وحدودها)</li></ul>',61)])])}const _=l(e,[["render",o]]);export{b as __pageData,_ as default};
